import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2016-DEC-14 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2016-DEC-14 :: Ceph Performance Weekly","date":"2017-01-11T00:00:00.000Z","updated":"2017-01-12T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueStore","OSD","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),o={name:"posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.md"};function s(a,l,n,_,p,u){return i(),t("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Igor, Mark, Alan, Sam, 等</p><p><strong>会议主题</strong>： Ceph分布式存储项目更新，包括OSD优化、性能测试、日志存储引擎选择等议题。</p><p><strong>关键细节</strong>：</p><ul><li><strong>OSD优化</strong>： <ul><li>Sage提交了一个OSD优化补丁，用于提升性能。</li><li>RBD在EC覆盖测试中表现良好，特别是在大型顺序写操作中，但在小随机写操作和文件存储中表现较差。</li><li>计划优化小写操作，提高效率，并开始在Red Hat进行BlueStore的缩放测试。</li></ul></li><li><strong>性能测试</strong>： <ul><li>使用新的对象存储性能基准进行测试，Igor正在测试并提供反馈。</li><li>预计在Crackit发布后会有所进展。</li></ul></li><li><strong>日志存储引擎选择</strong>： <ul><li>讨论了使用RocksDB作为日志存储引擎的优缺点。</li><li>分析了其他存储引擎，如WiredTiger、TokuDB等，并评估了其适用性。</li><li>认为在Luminous版本中，RocksDB是最合适的选择，但需要进一步改进。</li></ul></li><li><strong>其他议题</strong>： <ul><li>讨论了Fast Dispatch优化。</li><li>讨论了DPDK的使用情况。</li><li>讨论了RDMA的工作进展。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续使用RocksDB作为日志存储引擎，并对其进行改进。</li><li>优化BlueStore，提高其在小随机写操作和文件存储中的性能。</li><li>进行更多的性能测试，以评估不同存储引擎的适用性。</li><li>继续关注RDMA和RDMA的工作进展。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Igor将继续测试新的对象存储性能基准，并提供反馈。</li><li>Mark将继续优化Fast Dispatch。</li><li>Alan将继续关注BlueStore的性能和优化。</li><li>其他团队成员将继续进行相关工作。</li></ul><p><strong>改进点</strong>：</p><ul><li>在OSD优化部分，更详细地描述了BlueStore在不同类型写操作中的表现。</li><li>在日志存储引擎选择部分，增加了对不同存储引擎的分析。</li><li>在其他议题部分，增加了对DPDK和RDMA的讨论。</li><li>在行动计划部分，明确了各个团队成员的具体任务。</li></ul>',12)])])}const D=e(o,[["render",s]]);export{c as __pageData,D as default};
